import{_ as e,c as a,o,ag as r}from"./chunks/framework._xRlcm3f.js";const m=JSON.parse('{"title":"语雀 API 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/common-yuque.md","filePath":"platforms/common-yuque.md","lastUpdated":1790228279000}'),n={name:"platforms/common-yuque.md"};function l(d,t,i,s,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="语雀-api-配置指南" tabindex="-1">语雀 API 配置指南 <a class="header-anchor" href="#语雀-api-配置指南" aria-label="Permalink to &quot;语雀 API 配置指南&quot;">​</a></h1><p>通过<strong>语雀 API Token</strong> 发布到语雀知识库。</p><blockquote><p>⚠️ 语雀 API 发布需要<strong>专业会员</strong>，这是语雀平台策略，不是插件问题。免费账号请改用「语雀网页版（Cookie 模式）」。</p></blockquote><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>语雀账号（专业会员）。</li><li>一个 <strong>API Token</strong>。</li></ol><h2 id="二、获取-token" tabindex="-1">二、获取 Token <a class="header-anchor" href="#二、获取-token" aria-label="Permalink to &quot;二、获取 Token&quot;">​</a></h2><p>语雀设置 → 访问令牌 → 生成。地址：<a href="https://www.yuque.com/settings/tokens" target="_blank" rel="noreferrer">https://www.yuque.com/settings/tokens</a></p><h2 id="三、配置" tabindex="-1">三、配置 <a class="header-anchor" href="#三、配置" aria-label="Permalink to &quot;三、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>语雀主页，如 <code>https://www.yuque.com/你的用户名</code></td></tr><tr><td>API 地址</td><td>默认语雀 v2 API，一般不改</td></tr><tr><td>用户名</td><td>与 Token 对应的语雀账号</td></tr><tr><td>Token</td><td>上面生成的访问令牌</td></tr><tr><td>知识库</td><td>验证通过后从下拉选择可写知识库</td></tr><tr><td>图床</td><td>语雀只有「不使用」与「PicGo」两项（无内置图床）。默认「不使用」，图片按原有地址引用，需保证图片可公网访问；要上传本地图片就选「PicGo」并在「图床设置」中配好上传通道</td></tr></tbody></table><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 拉取知识库列表 → 选知识库 → 保存。</li><li>快速发布 → 选语雀 → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>提示「权限不足」</strong>：语雀 API 需要专业会员，免费版改用语雀网页版。</li><li><strong>知识库列表为空</strong>：确认 Token 正确、账号下有可写知识库、先点验证。</li><li><strong>不能改已发布文档所属知识库</strong>：语雀 API 平台限制，删除原绑定后重新选库发布。</li></ul>',13)])])}const p=e(n,[["render",l]]);export{m as __pageData,p as default};
